/**
 * apply_design end to end on the Manifold kernel: the design is ONE design_source step, regenerated by set_parameter / edit_step_params,
 * anchors resolve on the real geometry, failures name the line and leave the document unchanged.
 */

import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { createManifoldKernel } from '@kernel-manifold/manifoldKernel';
import { setGeometryKernel } from '@core/geometry/kernel';
import { execute } from '@core/commands/registry';
import { createEmptyDocument, type CadDocument } from '@core/model/types';
import type { CommandResult } from '@core/commands/types';

const BRACKET = `design bracket units=mm
param t = 6mm
param w = 80mm

add_box  base    size=[120, w, t]  position=[0, 0, t/2]
add_box  upright size=[120, t, 60]  on=base.top align=back
boolean  body    op=union a=base b=upright
add_hole drilled target=body face=base.bottom pointsFrame=world_xy points=[[-45, -(w/2-15)], [45, -(w/2-15)]] hole.kind=simple hole.diameter=8mm extent.kind=through_all

check bbox   of=drilled expect == [120, w, 66] ± 0.01
check volume of=drilled expect ~= 120*w*t + 120*t*60 - 2*pi*16*t ± 1%
`;

const apply = (doc: CadDocument, source: string, set?: Record<string, number>): CommandResult =>
  execute(doc, 'apply_design', set === undefined ? { source } : { source, set });
const size = (doc: CadDocument, id = doc.order.at(-1) ?? ''): number[] =>
  (execute(doc, 'measure_bounding_box', { entityId: id }).data as { size: number[] }).size;
const box = (doc: CadDocument, id: string): { min: number[]; max: number[] } =>
  execute(doc, 'measure_bounding_box', { entityId: id }).data as { min: number[]; max: number[] };

let bracket: CadDocument;

beforeAll(async () => {
  setGeometryKernel(await createManifoldKernel());
  bracket = apply(createEmptyDocument(), BRACKET).document;
});
afterAll(() => setGeometryKernel(null));

describe('apply_design', () => {
  it('records one design_source step holding the source, with =param markers', () => {
    expect(bracket.featureHistory.map((s) => s.name)).toEqual(['design_source']);
    expect(bracket.featureHistory[0]?.params).toEqual({ source: BRACKET, reads: { t: '=t', w: '=w' } });
    expect(bracket.parameters['w']?.value).toBe(80);
    expect(size(bracket)).toEqual([120, 80, 66]);
  });

  it('reports aliases and passing checks', () => {
    const r = apply(createEmptyDocument(), BRACKET);
    expect(r.summary).toMatch(/recorded the design .*2\/2 checks pass/);
    const data = r.data as { checks: { pass: boolean; line: number }[]; aliases: Record<string, string[]> };
    expect(data.checks.map((c) => [c.line, c.pass])).toEqual([
      [10, true],
      [11, true],
    ]);
    expect(Object.keys(data.aliases)).toEqual(['base', 'upright', 'body', 'drilled']);
  });

  it('places with on= / align=: the upright stands on the base top, flush with its back', () => {
    const partial = apply(createEmptyDocument(), BRACKET.split('\nboolean')[0] ?? '').document;
    const upright = box(partial, partial.order[1] ?? '');
    expect(upright.min[2]).toBeCloseTo(6);
    expect(upright.max[1]).toBeCloseTo(40);
  });

  it('is pure', () => {
    const doc = createEmptyDocument();
    const before = structuredClone(doc);
    apply(doc, BRACKET);
    expect(doc).toEqual(before);
  });

  it('set= overrides a param default; an existing parameter wins over the default', () => {
    expect(size(apply(createEmptyDocument(), BRACKET, { w: 50 }).document)).toEqual([120, 50, 66]);
    const preset = execute(createEmptyDocument(), 'set_parameter', { name: 'w', expression: '60' }).document;
    expect(size(apply(preset, BRACKET).document)).toEqual([120, 60, 66]);
  });

  it('applying again replaces the design (still one step)', () => {
    const r = apply(bracket, BRACKET.replace('size=[120, w, t]', 'size=[150, w, t]').replace('[120, t, 60]', '[150, t, 60]'));
    expect(r.summary).toMatch(/replaced the design/);
    expect(r.document.featureHistory.map((s) => s.name)).toEqual(['design_source']);
    expect(size(r.document)).toEqual([150, 80, 66]);
  });

  it('sets the document units from the header', () => {
    const r = apply(createEmptyDocument(), 'design part units=m\nadd_box b size=[1, 2, 3]');
    expect(r.document.units).toBe('m');
  });
});

describe('regeneration: the recipe is the source', () => {
  it('set_parameter regenerates the whole design, anchors included; ids stay stable', () => {
    const w = execute(bracket, 'set_parameter', { name: 'w', expression: '100' });
    const t = execute(w.document, 'set_parameter', { name: 't', expression: '10' });
    expect(t.summary).toMatch(/regenerated 1 dependent/);
    expect(size(t.document)).toEqual([120, 100, 70]);
    expect(t.document.order).toEqual(bracket.order);
    expect(t.document.parameters['w']?.value).toBe(100);
  });

  it('edit_step_params with a new source regenerates', () => {
    const step = bracket.featureHistory[0];
    const params = { ...(step?.params as object), source: BRACKET.replace('[120, t, 60]', '[120, t, 90]') };
    const r = execute(bracket, 'edit_step_params', { stepId: step?.id ?? '', params });
    expect(size(r.document)).toEqual([120, 80, 96]);
  });

  it('a UI step recorded after the design survives a regeneration', () => {
    const moved = execute(bracket, 'move_entities', { ids: [bracket.order.at(-1) ?? ''], delta: [0, 0, 100] });
    const w = execute(moved.document, 'set_parameter', { name: 'w', expression: '100' });
    const result = box(w.document, w.document.order.at(-1) ?? '');
    expect(result.min[2]).toBeCloseTo(100);
    expect((result.max[1] ?? 0) - (result.min[1] ?? 0)).toBeCloseTo(100);
  });

  it('a regeneration that breaks a line is reported with that line', () => {
    const r = execute(bracket, 'set_parameter', { name: 'w', expression: '8' });
    expect(r.error?.code).toBe('HIST_STEP_FAILED');
    expect(r.summary).toMatch(/design_source.*line 8/);
  });
});

describe('failures name the line and change nothing', () => {
  const failing = (source: string): CommandResult => {
    const doc = createEmptyDocument();
    const r = apply(doc, source);
    expect(r.document).toBe(doc);
    return r;
  };

  it('unknown command, with suggestions', () => {
    const r = failing('param t = 6\nadd_bx a size=[1,1,1]');
    expect(r.error?.code).toBe('DESIGN_UNKNOWN_COMMAND');
    expect(r.error?.paths).toEqual(['line 2']);
    expect(r.error?.remediation).toMatch(/add_box/);
  });

  it('unknown param lists the params', () => {
    const r = failing('add_box a sise=[1,1,1]');
    expect(r.error?.code).toBe('DESIGN_UNKNOWN_PARAM');
    expect(r.error?.remediation).toMatch(/size/);
  });

  it('a failing command line rolls everything back, units and parameters included', () => {
    const r = failing(BRACKET.replace('points=[[-45, -(w/2-15)], [45, -(w/2-15)]]', 'points=[[500, 500]]'));
    expect(r.error?.code).toBe('DESIGN_STEP_FAILED');
    expect(r.error?.paths).toEqual(['line 8']);
  });

  it('a consumed alias used as an entity names its consumer', () => {
    const r = failing(
      'add_box a size=[2,2,2]\nadd_box b size=[1,1,1] position=[1,1,1]\nboolean c op=union a=a b=b\nmove_entities _ ids=[a] delta=[1,0,0]',
    );
    expect(r.error?.code).toBe('DESIGN_ALIAS_CONSUMED');
    expect(r.error?.remediation).toMatch(/Use c/);
  });

  it('unknown anchor and unknown parameter suggest close names', () => {
    expect(failing('add_box base size=[1,1,1]\nadd_box b size=[1,1,1] on=bas.top').error?.remediation).toMatch(/base/);
    expect(failing('param width = 2\nadd_box b size=[widht,1,1]').error?.remediation).toMatch(/width/);
  });

  it('syntax errors', () => {
    expect(failing('add_box a size=[1,1,1').error?.code).toBe('DESIGN_SYNTAX');
    expect(failing('for i in 0..2 {\nadd_box _ size=[1,1,1]').error?.code).toBe('DESIGN_SYNTAX');
  });

  it('set naming an undeclared param', () => {
    expect(apply(createEmptyDocument(), BRACKET, { nope: 1 }).error?.code).toBe('DESIGN_UNKNOWN_PARAMETER');
  });
});

describe('loops', () => {
  it('for + {i} aliases + set_parameter on the count regenerates', () => {
    const source =
      'param n = 3\nfor i in 0..n-1 {\n  add_cylinder post{i} radius=2 height=10 position=[i*10, 0, 5]\n}\ncheck bbox of=post2 expect == [4, 4, 10]';
    const r = apply(createEmptyDocument(), source);
    expect(r.document.order).toHaveLength(3);
    expect(r.summary).toMatch(/1\/1 checks pass/);
    expect(execute(r.document, 'set_parameter', { name: 'n', expression: '5' }).document.order).toHaveLength(5);
  });
});
